INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'efb28c24-4b77-5c47-9420-4156dec7a7a5'::uuid, '43265c75-a826-5f28-a3b5-3bb86fc75e05'::uuid, 'RYAD SOFIA Martil', 'Situé à seulement 1.5 Km de la plage de Martil et 1.5 Km du centre ville, une résidence dans un parc paysager où qualité rimera avec élégance et modernité. Bénéficiant de prestations de confort et à proximité de toutes les commodités nécessaires, ce projet est en plus un véritable havre de paix qui saura vous apporter calme et détente par ces jardins privatifs et ses allées débordantes de lumières. Ce projet d''une centaine d''Hectares est l''extension naturelle de la ville de Martil qui fait partie de la province de Tétouan. L''ensemble des habitations sera en résidence fermée, avec gardiennage, espaces verts et piscine pour le moyen standing et habitations de luxe. Venez découvrir un large choix de biens immobiliers à savoir : logements sociaux et moyen standing, des villas moyen et haut standing de différentes superficies, des lots de terrain pour investisseurs et particuliers, des commerces de proximité, ainsi qu''un mall.', 'Martil', 'd''El-Jadida', 'seulement 1.5 Km de la plage de Martil et 1.5 Km du centre ville, une résidence dans un parc paysager où qualité rimera', '20190', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'livre', 'non_determine', 100, NULL, NULL, NULL, $j$[]$j$::jsonb, 'Villa | Lot de terrain', 'Piscine ,  Jardin ,  Sécurité ,  Commerces ,  Mosquée ,  Espace vert', 'Mosquée ,  Centre commercial ,  Plage ,  Commerces ,  Parc', false, 320000.0, 320000.0, 320000.0, 'MAD', NULL, '43265c75-a826-5f28-a3b5-3bb86fc75e05', 'Anassi', 'https://www.groupejamai.com/', $j$[]$j$::jsonb, $j${"source_project_id": "efb28c24-4b77-5c47-9420-4156dec7a7a5", "chridari_ref": "KRX-PRJ-d0b1af4ddfde", "projet_id_legacy": "KRX-PRJ-d0b1af4ddfde", "equipe_realisation_mentions": "Maître d'ouvrage: Groupe Jamai", "url_source": "https://www.groupejamai.com/projects/show/ryad-sofia-martil/", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = 'efb28c24-4b77-5c47-9420-4156dec7a7a5'::uuid OR x.attributes->>'source_project_id' = 'efb28c24-4b77-5c47-9420-4156dec7a7a5');
